create or replace function public.create_abrigo(p_key_hash text) returns table(id uuid, created_at timestamptz, last_sync_at timestamptz) language plpgsql security definer set search_path = public as $$ begin if coalesce(length(trim(p_key_hash)),0) < 32 then raise exception 'invalid request'; end if; return query insert into abrigos(key_hash) values (p_key_hash) on conflict(key_hash) do update set updated_at=now() returning abrigos.id,abrigos.created_at,abrigos.last_sync_at; end $$;
create or replace function public.find_abrigo_by_key_hash(p_key_hash text) returns table(id uuid, created_at timestamptz, last_sync_at timestamptz) language sql security definer set search_path = public as $$ select a.id,a.created_at,a.last_sync_at from abrigos a where a.key_hash=p_key_hash limit 1 $$;
create or replace function public.save_abrigo_backup(p_key_hash text,p_version integer,p_payload jsonb) returns boolean language plpgsql security definer set search_path = public as $$ declare aid uuid; begin select id into aid from abrigos where key_hash=p_key_hash; if aid is null or p_version < 1 or p_payload is null then raise exception 'invalid request'; end if; insert into abrigo_backups(abrigo_id,version,payload) values(aid,p_version,p_payload) on conflict(abrigo_id) do update set version=excluded.version,payload=excluded.payload,updated_at=now(); return true; end $$;
create or replace function public.get_abrigo_backup(p_key_hash text) returns table(version integer,payload jsonb,created_at timestamptz,updated_at timestamptz) language sql security definer set search_path = public as $$ select b.version,b.payload,b.created_at,b.updated_at from abrigo_backups b join abrigos a on a.id=b.abrigo_id where a.key_hash=p_key_hash limit 1 $$;
create or replace function public.register_abrigo_device(p_key_hash text,p_device_id text,p_device_name text) returns table(id uuid,created_at timestamptz,last_sync_at timestamptz) language plpgsql security definer set search_path = public as $$ declare aid uuid; begin select id into aid from abrigos where key_hash=p_key_hash; if aid is null or coalesce(length(trim(p_device_id)),0)=0 then raise exception 'invalid request'; end if; return query insert into abrigo_devices(abrigo_id,device_id,device_name) values(aid,p_device_id,left(trim(p_device_name),120)) on conflict(abrigo_id,device_id) do update set device_name=excluded.device_name returning abrigo_devices.id,abrigo_devices.created_at,abrigo_devices.last_sync_at; end $$;
revoke all on function public.create_abrigo(text),public.find_abrigo_by_key_hash(text),public.save_abrigo_backup(text,integer,jsonb),public.get_abrigo_backup(text),public.register_abrigo_device(text,text,text) from public;
grant execute on function public.create_abrigo(text),public.find_abrigo_by_key_hash(text),public.save_abrigo_backup(text,integer,jsonb),public.get_abrigo_backup(text),public.register_abrigo_device(text,text,text) to anon;
